#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate the human-readable VAO 0.5.0 field reference from JSON Schema."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parent.parent
DEFAULT_SCHEMA = ROOT / "Schemas" / "vao-manifest-0.5.0.schema.json"
DEFAULT_OUTPUT = ROOT / "Docs" / "VAO_SCHEMA_REFERENCE_0.5.0.md"


def contract(value: dict[str, Any] | bool) -> str:
    if value is True:
        return "any JSON value"
    if value is False:
        return "no value permitted"
    parts: list[str] = []
    if "$ref" in value:
        parts.append(
            f"[`{value['$ref'].split('/')[-1]}`](#{value['$ref'].split('/')[-1].lower()})"
        )
    if "const" in value:
        parts.append(f"constant `{json.dumps(value['const'], ensure_ascii=False)}`")
    if "enum" in value:
        parts.append(
            "one of "
            + ", ".join(
                f"`{json.dumps(item, ensure_ascii=False)}`" for item in value["enum"]
            )
        )
    if "type" in value:
        parts.append(f"type `{value['type']}`")
    if "format" in value:
        parts.append(f"format `{value['format']}`")
    if "pattern" in value:
        parts.append(f"pattern `{value['pattern']}`")
    for key, label in (
        ("minimum", "minimum"),
        ("exclusiveMinimum", "exclusive minimum"),
        ("maximum", "maximum"),
        ("minLength", "minimum length"),
        ("minItems", "minimum items"),
        ("maxItems", "maximum items"),
        ("uniqueItems", "unique items"),
        ("minProperties", "minimum properties"),
        ("maxProperties", "maximum properties"),
    ):
        if key in value:
            parts.append(f"{label} `{json.dumps(value[key])}`")
    if "items" in value and isinstance(value["items"], dict):
        parts.append("items: " + contract(value["items"]))
    if "oneOf" in value:
        parts.append(f"one of {len(value['oneOf'])} alternatives")
    if "anyOf" in value:
        parts.append(f"any of {len(value['anyOf'])} alternatives")
    if value.get("additionalProperties") is False:
        parts.append("closed object")
    return "; ".join(parts) or "schema-defined value"


def section(name: str, value: dict[str, Any]) -> list[str]:
    lines = [f"## {name}", "", f"JSON Pointer: `#/$defs/{name}`", ""]
    if value.get("description"):
        lines.extend([value["description"], ""])
    lines.extend([f"Contract: {contract(value)}", ""])
    properties = value.get("properties")
    if not isinstance(properties, dict):
        return lines
    required = set(value.get("required", []))
    lines.extend(["| Property | Required | Contract |", "| --- | --- | --- |"])
    for property_name, property_schema in properties.items():
        rendered = contract(property_schema).replace("|", "\\|")
        lines.append(
            f"| `{property_name}` | {'yes' if property_name in required else 'no'} | {rendered} |"
        )
    lines.append("")
    return lines


def generate(schema: dict[str, Any]) -> str:
    lines = [
        "# VAO 0.5.0 schema field reference",
        "",
        "> Generated by `Tools/generate_schema_reference.py` from the normative manifest JSON Schema. Do not edit by hand. When this reference and the schema differ, the schema controls syntax.",
        "",
        f"- Schema ID: `{schema['$id']}`",
        f"- JSON Schema dialect: `{schema['$schema']}`",
        "",
        "## Root manifest",
        "",
        "Required properties: "
        + ", ".join(f"`{item}`" for item in schema.get("required", []))
        + ".",
        "",
        "| Property | Required | Contract |",
        "| --- | --- | --- |",
    ]
    required = set(schema.get("required", []))
    for name, value in schema.get("properties", {}).items():
        rendered = contract(value).replace("|", "\\|")
        lines.append(
            f"| `{name}` | {'yes' if name in required else 'no'} | {rendered} |"
        )
    lines.extend(["", "## Definition index", ""])
    for name in schema.get("$defs", {}):
        lines.append(f"- [{name}](#{name.lower()})")
    lines.append("")
    for name, value in schema.get("$defs", {}).items():
        lines.extend(section(name, value))
    return "\n".join(lines).rstrip() + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--schema", type=Path, default=DEFAULT_SCHEMA)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    rendered = generate(json.loads(args.schema.read_text(encoding="utf-8")))
    if args.check:
        if (
            not args.output.exists()
            or args.output.read_text(encoding="utf-8") != rendered
        ):
            print(f"OUT OF DATE: {args.output}")
            return 1
        print(f"CURRENT: {args.output}")
        return 0
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(rendered, encoding="utf-8")
    print(f"WROTE: {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
